const input = require("fs").readFileSync(0, "utf8");

function countNQueens(n) {
  const cols = new Array(n).fill(false);
  const downDiagonals = new Array(2 * n - 1).fill(false); // index row - col + n - 1
  const upDiagonals = new Array(2 * n - 1).fill(false); // index row + col

  // Places a queen in this row and in every row below it.
  function place(row) {
    if (row === n) {
      return 1;
    }
    let count = 0;
    for (let col = 0; col < n; col++) {
      const down = row - col + n - 1;
      const up = row + col;
      if (cols[col] || downDiagonals[down] || upDiagonals[up]) {
        continue;
      }
      cols[col] = true;
      downDiagonals[down] = true;
      upDiagonals[up] = true;
      count += place(row + 1);
      cols[col] = false;
      downDiagonals[down] = false;
      upDiagonals[up] = false;
    }
    return count;
  }

  return place(0);
}

const n = Number(input.trim());
console.log(countNQueens(n));

