#include <iostream>
#include <vector>

struct Board {
    int n;
    std::vector<bool> cols;
    std::vector<bool> downDiagonals; // index row - col + n - 1
    std::vector<bool> upDiagonals;   // index row + col
};

// Places a queen in this row and in every row below it.
int place(Board& board, int row) {
    int n = board.n;
    if (row == n) {
        return 1;
    }
    int count = 0;
    for (int col = 0; col < n; col++) {
        int down = row - col + n - 1;
        int up = row + col;
        if (board.cols[col] || board.downDiagonals[down] || board.upDiagonals[up]) {
            continue;
        }
        board.cols[col] = true;
        board.downDiagonals[down] = true;
        board.upDiagonals[up] = true;
        count += place(board, row + 1);
        board.cols[col] = false;
        board.downDiagonals[down] = false;
        board.upDiagonals[up] = false;
    }
    return count;
}

int countNQueens(int n) {
    Board board{n, std::vector<bool>(n), std::vector<bool>(2 * n - 1), std::vector<bool>(2 * n - 1)};
    return place(board, 0);
}

int main() {
    int n;
    std::cin >> n;
    std::cout << countNQueens(n) << "\n";
    return 0;
}

