package main

import "fmt"

func countNQueens(n int) int {
	cols := make([]bool, n)
	downDiagonals := make([]bool, 2*n-1) // index row - col + n - 1
	upDiagonals := make([]bool, 2*n-1)   // index row + col

	// Places a queen in this row and in every row below it.
	var place func(row int) int
	place = func(row int) int {
		if row == n {
			return 1
		}
		count := 0
		for col := 0; col < n; col++ {
			down, up := row-col+n-1, row+col
			if cols[col] || downDiagonals[down] || upDiagonals[up] {
				continue
			}
			cols[col], downDiagonals[down], upDiagonals[up] = true, true, true
			count += place(row + 1)
			cols[col], downDiagonals[down], upDiagonals[up] = false, false, false
		}
		return count
	}

	return place(0)
}

func main() {
	var n int
	fmt.Scan(&n)
	fmt.Println(countNQueens(n))
}

